//! Automated benchmark runner for neural network layers.
//!
//! Benchmarks DenseLayer (MLP), Conv2DLayer (CNN), LstmLayer, and
//! MultiHeadAttentionLayer using synthetic data generated by SimpleRng.
//! Results are serialized to JSON and optionally saved to a timestamped file.
//! Regression detection is available via the `--check-regression` flag.
//!
//! # Usage
//!
//! ```bash
//! # Run all benchmarks and print JSON to stdout
//! cargo run --release --bin run_benchmarks
//!
//! # Run and save results to benchmarks/results/TIMESTAMP.json
//! cargo run --release --bin run_benchmarks -- --save-results
//!
//! # Run and check for regressions against benchmarks/baseline.json
//! cargo run --release --bin run_benchmarks -- --check-regression
//! ```

use rust_neural_networks::benchmark::{
    measure_layer_training_step, BenchmarkConfig, BenchmarkResult,
};
use rust_neural_networks::layers::{
    Conv2DLayer, DenseLayer, Layer, LstmLayer, MultiHeadAttentionLayer,
};
use rust_neural_networks::utils::rng::SimpleRng;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;
use std::time::{SystemTime, UNIX_EPOCH};

// ============================================================================
// Configuration Structures
// ============================================================================

/// MLP architecture configuration loaded from benchmark_config.json.
#[derive(Debug, Deserialize)]
struct MlpConfig {
    input_size: usize,
    hidden_size: usize,
    #[allow(dead_code)]
    output_size: usize,
}

/// CNN architecture configuration loaded from benchmark_config.json.
#[derive(Debug, Deserialize)]
struct CnnConfig {
    in_channels: usize,
    filters: usize,
    kernel_size: usize,
    stride: usize,
    padding: usize,
    height: usize,
    width: usize,
}

/// LSTM architecture configuration loaded from benchmark_config.json.
#[derive(Debug, Deserialize)]
struct LstmConfig {
    input_size: usize,
    hidden_size: usize,
    output_size: usize,
}

/// Attention architecture configuration loaded from benchmark_config.json.
#[derive(Debug, Deserialize)]
struct AttentionConfig {
    embed_dim: usize,
    num_heads: usize,
}

/// Architecture configurations bundled together.
#[derive(Debug, Deserialize)]
struct ArchitectureConfigs {
    mlp: MlpConfig,
    cnn: CnnConfig,
    lstm: LstmConfig,
    attention: AttentionConfig,
}

/// Full benchmark configuration file structure.
///
/// Extends the library's BenchmarkConfig with architecture-specific parameters
/// that configure which layers to benchmark and with what dimensions.
#[derive(Debug, Deserialize)]
struct FullBenchmarkConfig {
    warmup_iterations: usize,
    measure_iterations: usize,
    batch_sizes: Vec<usize>,
    architectures: ArchitectureConfigs,
}

impl FullBenchmarkConfig {
    /// Extract the library BenchmarkConfig (timing params only).
    fn to_benchmark_config(&self) -> BenchmarkConfig {
        BenchmarkConfig {
            warmup_iterations: self.warmup_iterations,
            measure_iterations: self.measure_iterations,
            batch_sizes: self.batch_sizes.clone(),
        }
    }
}

// ============================================================================
// Baseline / Regression Structures
// ============================================================================

/// Per-architecture threshold for regression detection.
#[derive(Debug, Deserialize)]
struct ArchitectureThreshold {
    name: String,
    max_acceptable_latency_ms: f64,
    min_acceptable_throughput_samples_per_sec: f64,
}

/// Top-level baseline.json structure.
#[derive(Debug, Deserialize)]
struct BaselineFile {
    architectures: Vec<ArchitectureThreshold>,
}

// ============================================================================
// Output Structures
// ============================================================================

/// Top-level JSON output written to stdout / results file.
#[derive(Debug, Serialize)]
struct BenchmarkOutput {
    /// Unix timestamp seconds when the run started.
    timestamp: u64,
    /// Human-readable ISO-like timestamp string.
    timestamp_str: String,
    /// All individual benchmark results.
    results: Vec<BenchmarkResult>,
}

// ============================================================================
// Helpers
// ============================================================================

/// Return current Unix epoch in seconds.
fn unix_timestamp_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

/// Generate a vector of random f32 values in [0, 1).
fn random_input(size: usize, rng: &mut SimpleRng) -> Vec<f32> {
    (0..size).map(|_| rng.next_f32()).collect()
}

// ============================================================================
// Benchmark Runners
// ============================================================================

/// Benchmark DenseLayer (MLP) forward + full training step for all batch sizes.
fn benchmark_mlp(
    cfg: &MlpConfig,
    bench_cfg: &BenchmarkConfig,
    rng: &mut SimpleRng,
) -> Vec<BenchmarkResult> {
    let mut results = Vec::new();

    for &batch_size in &bench_cfg.batch_sizes {
        let mut layer = DenseLayer::new(cfg.input_size, cfg.hidden_size, rng);
        let input = random_input(batch_size * cfg.input_size, rng);
        let grad_output = random_input(batch_size * cfg.hidden_size, rng);

        let name = format!(
            "MLP Dense {}→{} (batch={})",
            cfg.input_size, cfg.hidden_size, batch_size
        );

        let result = measure_layer_training_step(
            &name,
            &mut layer,
            &input,
            &grad_output,
            batch_size,
            0.01,
            bench_cfg,
        );
        results.push(result);
    }

    results
}

/// Benchmark Conv2DLayer (CNN) forward + full training step for all batch sizes.
fn benchmark_cnn(
    cfg: &CnnConfig,
    bench_cfg: &BenchmarkConfig,
    rng: &mut SimpleRng,
) -> Vec<BenchmarkResult> {
    let mut results = Vec::new();

    for &batch_size in &bench_cfg.batch_sizes {
        let mut layer = Conv2DLayer::new(
            cfg.in_channels,
            cfg.filters,
            cfg.kernel_size,
            cfg.padding as isize,
            cfg.stride,
            cfg.height,
            cfg.width,
            rng,
        );

        let input_size = layer.input_size();
        let output_size = layer.output_size();
        let input = random_input(batch_size * input_size, rng);
        let grad_output = random_input(batch_size * output_size, rng);

        let name = format!(
            "CNN Conv2D {}ch→{}ch {}x{} (batch={})",
            cfg.in_channels, cfg.filters, cfg.height, cfg.width, batch_size
        );

        let result = measure_layer_training_step(
            &name,
            &mut layer,
            &input,
            &grad_output,
            batch_size,
            0.01,
            bench_cfg,
        );
        results.push(result);
    }

    results
}

/// Benchmark LstmLayer forward + full training step for all batch sizes.
fn benchmark_lstm(
    cfg: &LstmConfig,
    bench_cfg: &BenchmarkConfig,
    rng: &mut SimpleRng,
) -> Vec<BenchmarkResult> {
    let mut results = Vec::new();

    for &batch_size in &bench_cfg.batch_sizes {
        let mut layer = LstmLayer::new(cfg.input_size, cfg.hidden_size, cfg.output_size, rng);
        layer.reset_state();

        let input = random_input(batch_size * cfg.input_size, rng);
        let grad_output = random_input(batch_size * cfg.output_size, rng);

        let name = format!(
            "LSTM {}→{}→{} (batch={})",
            cfg.input_size, cfg.hidden_size, cfg.output_size, batch_size
        );

        let result = measure_layer_training_step(
            &name,
            &mut layer,
            &input,
            &grad_output,
            batch_size,
            0.01,
            bench_cfg,
        );
        results.push(result);
    }

    results
}

/// Benchmark MultiHeadAttentionLayer forward for all batch sizes.
///
/// Uses seq_len=1 per time step (single token) since the config specifies
/// only `embed_dim` and `num_heads`; seq_len is inferred at runtime.
fn benchmark_attention(
    cfg: &AttentionConfig,
    bench_cfg: &BenchmarkConfig,
    rng: &mut SimpleRng,
) -> Vec<BenchmarkResult> {
    let mut results = Vec::new();

    // Use seq_len=8 (a common small sequence for benchmarking)
    let seq_len: usize = 8;

    for &batch_size in &bench_cfg.batch_sizes {
        let layer = MultiHeadAttentionLayer::new(cfg.embed_dim, cfg.num_heads, rng);

        // Input: [batch_size * seq_len, embed_dim]
        let input = random_input(batch_size * seq_len * cfg.embed_dim, rng);

        let name = format!(
            "Attention d_model={} heads={} seq={} (batch={})",
            cfg.embed_dim, cfg.num_heads, seq_len, batch_size
        );

        // Attention layer only supports forward benchmark via measure_layer_forward
        // since its input_size() / output_size() are per-token (embed_dim) but we
        // pass a full sequence; use the generic forward harness directly.
        let output_size = layer.output_size();
        let mut output = vec![0.0f32; batch_size * seq_len * output_size];

        // Warmup
        for _ in 0..bench_cfg.warmup_iterations {
            layer.forward(&input, &mut output, batch_size);
        }

        // Measurement
        let mut durations_ms: Vec<f64> = Vec::with_capacity(bench_cfg.measure_iterations);
        for _ in 0..bench_cfg.measure_iterations {
            let start = std::time::Instant::now();
            layer.forward(&input, &mut output, batch_size);
            durations_ms.push(start.elapsed().as_secs_f64() * 1_000.0);
        }

        let forward_stats = compute_stats_inline(&durations_ms, batch_size);

        let result = BenchmarkResult {
            name,
            batch_size,
            input_size: layer.input_size(),
            output_size: layer.output_size(),
            parameter_count: layer.parameter_count(),
            forward_stats,
            training_stats: None,
        };
        results.push(result);
    }

    results
}

/// Inline stats computation (mirrors benchmark.rs compute_stats, needed since it's private).
fn compute_stats_inline(
    samples: &[f64],
    batch_size: usize,
) -> rust_neural_networks::benchmark::BenchmarkStats {
    assert!(!samples.is_empty(), "benchmark samples must not be empty");

    let n = samples.len() as f64;
    let mean_ms = samples.iter().sum::<f64>() / n;

    let variance = samples.iter().map(|&x| (x - mean_ms).powi(2)).sum::<f64>() / n;
    let std_dev_ms = variance.sqrt();

    let min_ms = samples.iter().cloned().fold(f64::INFINITY, f64::min);
    let max_ms = samples.iter().cloned().fold(f64::NEG_INFINITY, f64::max);

    let mut sorted = samples.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let mid = sorted.len() / 2;
    let median_ms = if sorted.len() % 2 == 0 {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    } else {
        sorted[mid]
    };

    let samples_per_second = if mean_ms > 0.0 {
        (batch_size as f64 / mean_ms) * 1_000.0
    } else {
        f64::INFINITY
    };

    rust_neural_networks::benchmark::BenchmarkStats {
        mean_ms,
        median_ms,
        std_dev_ms,
        min_ms,
        max_ms,
        samples_per_second,
    }
}

// ============================================================================
// Regression Detection
// ============================================================================

/// Check benchmark results against a baseline file for regressions.
///
/// Returns `Ok(())` if all checks pass, or `Err(Vec<String>)` with a list
/// of regression messages if any threshold is violated.
fn check_regression(results: &[BenchmarkResult], baseline_path: &str) -> Result<(), Vec<String>> {
    let baseline_json = match fs::read_to_string(baseline_path) {
        Ok(s) => s,
        Err(e) => {
            return Err(vec![format!(
                "Failed to read baseline file '{}': {}",
                baseline_path, e
            )]);
        }
    };

    let baseline: BaselineFile = match serde_json::from_str(&baseline_json) {
        Ok(b) => b,
        Err(e) => {
            return Err(vec![format!(
                "Failed to parse baseline file '{}': {}",
                baseline_path, e
            )]);
        }
    };

    // Build a lookup map: architecture name → threshold
    let mut thresholds: HashMap<String, &ArchitectureThreshold> = HashMap::new();
    for threshold in &baseline.architectures {
        thresholds.insert(threshold.name.clone(), threshold);
    }

    let mut violations: Vec<String> = Vec::new();

    for result in results {
        // Determine which architecture this result belongs to based on name prefix
        let arch_name = if result.name.starts_with("MLP") {
            "mlp"
        } else if result.name.starts_with("CNN") {
            "cnn"
        } else if result.name.starts_with("LSTM") {
            "lstm"
        } else if result.name.starts_with("Attention") {
            "attention"
        } else {
            continue;
        };

        if let Some(threshold) = thresholds.get(arch_name) {
            // Check forward latency
            if result.forward_stats.mean_ms > threshold.max_acceptable_latency_ms {
                violations.push(format!(
                    "REGRESSION: {} forward mean_ms={:.3} exceeds max={:.1}ms",
                    result.name, result.forward_stats.mean_ms, threshold.max_acceptable_latency_ms
                ));
            }

            // Check forward throughput
            if result.forward_stats.samples_per_second
                < threshold.min_acceptable_throughput_samples_per_sec
            {
                violations.push(format!(
                    "REGRESSION: {} forward samples/sec={:.1} below min={:.1}",
                    result.name,
                    result.forward_stats.samples_per_second,
                    threshold.min_acceptable_throughput_samples_per_sec
                ));
            }

            // Also check training stats if present
            if let Some(ref training) = result.training_stats {
                if training.mean_ms > threshold.max_acceptable_latency_ms {
                    violations.push(format!(
                        "REGRESSION: {} training mean_ms={:.3} exceeds max={:.1}ms",
                        result.name, training.mean_ms, threshold.max_acceptable_latency_ms
                    ));
                }

                if training.samples_per_second < threshold.min_acceptable_throughput_samples_per_sec
                {
                    violations.push(format!(
                        "REGRESSION: {} training samples/sec={:.1} below min={:.1}",
                        result.name,
                        training.samples_per_second,
                        threshold.min_acceptable_throughput_samples_per_sec
                    ));
                }
            }
        }
    }

    if violations.is_empty() {
        Ok(())
    } else {
        Err(violations)
    }
}

// ============================================================================
// Main
// ============================================================================

fn main() {
    let args: Vec<String> = env::args().collect();

    let check_regression_flag = args.iter().any(|a| a == "--check-regression");
    let save_results_flag = args.iter().any(|a| a == "--save-results");

    // ---- Load benchmark configuration ----
    let config_path = "config/benchmarks/benchmark_config.json";
    let config_json = match fs::read_to_string(config_path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Error: Failed to read config file '{}': {}", config_path, e);
            process::exit(1);
        }
    };

    let full_config: FullBenchmarkConfig = match serde_json::from_str(&config_json) {
        Ok(c) => c,
        Err(e) => {
            eprintln!(
                "Error: Failed to parse config file '{}': {}",
                config_path, e
            );
            process::exit(1);
        }
    };

    let bench_cfg = full_config.to_benchmark_config();

    eprintln!(
        "Running benchmarks: warmup={}, measure={}, batch_sizes={:?}",
        bench_cfg.warmup_iterations, bench_cfg.measure_iterations, bench_cfg.batch_sizes
    );

    // ---- Generate all benchmark results ----
    let mut rng = SimpleRng::new(42);
    let mut all_results: Vec<BenchmarkResult> = Vec::new();

    eprintln!("Benchmarking MLP (DenseLayer)...");
    let mlp_results = benchmark_mlp(&full_config.architectures.mlp, &bench_cfg, &mut rng);
    all_results.extend(mlp_results);

    eprintln!("Benchmarking CNN (Conv2DLayer)...");
    let cnn_results = benchmark_cnn(&full_config.architectures.cnn, &bench_cfg, &mut rng);
    all_results.extend(cnn_results);

    eprintln!("Benchmarking LSTM (LstmLayer)...");
    let lstm_results = benchmark_lstm(&full_config.architectures.lstm, &bench_cfg, &mut rng);
    all_results.extend(lstm_results);

    eprintln!("Benchmarking Attention (MultiHeadAttentionLayer)...");
    let attention_results =
        benchmark_attention(&full_config.architectures.attention, &bench_cfg, &mut rng);
    all_results.extend(attention_results);

    eprintln!("Benchmarks complete ({} results).", all_results.len());

    // ---- Build output ----
    let timestamp = unix_timestamp_secs();
    let output = BenchmarkOutput {
        timestamp,
        timestamp_str: format!("{}", timestamp),
        results: all_results,
    };

    let json_output = match serde_json::to_string_pretty(&output) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Error: Failed to serialize results: {}", e);
            process::exit(1);
        }
    };

    // ---- Print JSON to stdout ----
    println!("{}", json_output);

    // ---- Optionally save results to timestamped file ----
    if save_results_flag {
        let results_dir = "benchmarks/results";
        if let Err(e) = fs::create_dir_all(results_dir) {
            eprintln!(
                "Warning: Failed to create results directory '{}': {}",
                results_dir, e
            );
        } else {
            let output_path = format!("{}/{}.json", results_dir, timestamp);
            match fs::write(&output_path, &json_output) {
                Ok(()) => eprintln!("Results saved to '{}'", output_path),
                Err(e) => eprintln!(
                    "Warning: Failed to save results to '{}': {}",
                    output_path, e
                ),
            }
        }
    }

    // ---- Check for regressions if requested ----
    if check_regression_flag {
        let baseline_path = "benchmarks/baseline.json";
        eprintln!("Checking regressions against '{}'...", baseline_path);

        match check_regression(&output.results, baseline_path) {
            Ok(()) => {
                eprintln!("Regression check PASSED: all results within baseline thresholds.");
            }
            Err(violations) => {
                eprintln!(
                    "Regression check FAILED: {} violation(s) detected:",
                    violations.len()
                );
                for v in &violations {
                    eprintln!("  {}", v);
                }
                process::exit(1);
            }
        }
    }
}
